// @generated by @frameless/solid; do not edit.
import { createSignal, For, Show } from 'solid-js';
import { createStore, reconcile } from 'solid-js/store';

export function TodoMvc(props: {
	onTrace: (name: string, detail: Record<string, unknown>, event: unknown) => void;
}) {
	const [todos, setTodos] = createStore([
		{ id: 't1', title: 'Taste JavaScript', done: true },
		{ id: 't2', title: 'Buy a unicorn', done: false },
	]);
	const [draft, setDraft] = createSignal('');
	let next = 3;
	const [filter, setFilter] = createSignal('all');
	const [editing, setEditing] = createSignal('');
	const [editDraft, setEditDraft] = createSignal('');
	const active = () => todos.filter((todo) => !todo.done).length;
	const completed = () => todos.filter((todo) => todo.done).length;
	const allDone = () => todos.length > 0 && todos.filter((todo) => !todo.done).length === 0;
	const remainingLabel = () =>
		todos.filter((todo) => !todo.done).length === 1 ? ' item left' : ' items left';
	return (
		<section class="todoapp" data-app="todomvc">
			<header class="header">
				<h1>todos</h1>
				<form
					class="new-todo-form"
					data-action="add"
					onClick={(event) => {
						props.onTrace('press', { area: 'new-todo' }, event);
					}}
					onSubmit={(event) => {
						event.preventDefault();
						const title = draft().trim();
						const item = { id: `t${next}`, title, done: false };
						setTodos(
							reconcile(title === '' ? todos : todos.concat(item), { key: 'id' }),
						);
						next = title === '' ? next : next + 1;
						setDraft('');
						props.onTrace('add', { id: item.id, title }, event);
					}}
				>
					<input
						class="new-todo"
						placeholder="What needs to be done?"
						data-action="new"
						value={draft()}
						attr:value={draft()}
						onInput={(event) => {
							setDraft(event.currentTarget.value);
						}}
					/>
				</form>
			</header>
			<Show when={todos.length > 0}>
				<main class="main">
					<input
						id="toggle-all"
						class="toggle-all"
						type="checkbox"
						data-action="toggle-all"
						checked={allDone()}
						onChange={(event) => {
							const done = event.currentTarget.checked;
							setTodos(
								reconcile(
									todos.map((todo) => ({ id: todo.id, title: todo.title, done })),
									{ key: 'id' },
								),
							);
							props.onTrace('toggle-all', { done }, event);
						}}
					/>
					<label for="toggle-all">Mark all as complete</label>
					<ul class="todo-list">
						<For each={todos}>
							{(todo) => (
								<li
									class={
										editing() === todo.id
											? 'editing'
											: todo.done
												? 'completed'
												: ''
									}
									data-oracle-todo-key={todo.id}
									hidden={
										filter() === 'active'
											? todo.done
											: filter() === 'completed'
												? !todo.done
												: false
									}
								>
									<Show
										when={editing() === todo.id}
										fallback={
											<div class="view">
												<input
													class="toggle"
													type="checkbox"
													data-toggle={todo.id}
													checked={todo.done}
													onChange={(event) => {
														const done = event.currentTarget.checked;
														setTodos(
															reconcile(
																todos.map((entry) =>
																	entry.id === todo.id
																		? {
																				id: entry.id,
																				title: entry.title,
																				done,
																			}
																		: entry,
																),
																{ key: 'id' },
															),
														);
														props.onTrace(
															'toggle',
															{ id: todo.id, done },
															event,
														);
													}}
												/>
												<button
													type="button"
													class="todo-title"
													data-title={todo.id}
													onClick={(event) => {
														const opened = event.detail === 2;
														setEditing(opened ? todo.id : editing());
														setEditDraft(
															opened ? todo.title : editDraft(),
														);
														props.onTrace(
															'edit',
															{ id: todo.id, opened },
															event,
														);
													}}
												>
													{todo.title}
												</button>
												<button
													type="button"
													class="destroy"
													data-destroy={todo.id}
													onClick={(event) => {
														setTodos(
															reconcile(
																todos.filter(
																	(entry) => entry.id !== todo.id,
																),
																{ key: 'id' },
															),
														);
														props.onTrace(
															'destroy',
															{ id: todo.id },
															event,
														);
													}}
												>
													x
												</button>
											</div>
										}
									>
										<form
											class="edit-form"
											data-commit={todo.id}
											onClick={(event) => {
												props.onTrace('press', { area: 'edit' }, event);
											}}
											onSubmit={(event) => {
												event.preventDefault();
												const title = editDraft().trim();
												setTodos(
													reconcile(
														title === ''
															? todos
															: todos.map((entry) =>
																	entry.id === todo.id
																		? {
																				id: entry.id,
																				title,
																				done: entry.done,
																			}
																		: entry,
																),
														{ key: 'id' },
													),
												);
												setEditing('');
												setEditDraft('');
												props.onTrace(
													'commit',
													{ id: todo.id, title },
													event,
												);
											}}
										>
											<input
												class="edit"
												data-edit={todo.id}
												value={editDraft()}
												attr:value={editDraft()}
												onInput={(event) => {
													setEditDraft(event.currentTarget.value);
												}}
											/>
											<button
												type="button"
												class="cancel-edit"
												data-revert={todo.id}
												onClick={(event) => {
													setEditing('');
													setEditDraft('');
													props.onTrace('revert', { id: todo.id }, event);
												}}
											>
												cancel
											</button>
										</form>
									</Show>
								</li>
							)}
						</For>
					</ul>
				</main>
			</Show>
			<Show when={todos.length > 0}>
				<footer class="footer">
					<span class="todo-count">
						<strong>{active()}</strong>
						{remainingLabel()}
					</span>
					<ul class="filters">
						<li>
							<a
								href="#/"
								data-filter="all"
								class={filter() === 'all' ? 'selected' : ''}
								onClick={(event) => {
									event.preventDefault();
									setFilter('all');
									props.onTrace('filter', { filter: 'all' }, event);
								}}
							>
								All
							</a>
						</li>
						<li>
							<a
								href="#/active"
								data-filter="active"
								class={filter() === 'active' ? 'selected' : ''}
								onClick={(event) => {
									event.preventDefault();
									setFilter('active');
									props.onTrace('filter', { filter: 'active' }, event);
								}}
							>
								Active
							</a>
						</li>
						<li>
							<a
								href="#/completed"
								data-filter="completed"
								class={filter() === 'completed' ? 'selected' : ''}
								onClick={(event) => {
									event.preventDefault();
									setFilter('completed');
									props.onTrace('filter', { filter: 'completed' }, event);
								}}
							>
								Completed
							</a>
						</li>
					</ul>
					<Show when={completed() > 0}>
						<button
							type="button"
							class="clear-completed"
							data-action="clear-completed"
							onClick={(event) => {
								const cleared = todos.filter((todo) => todo.done).length;
								setTodos(
									reconcile(
										todos.filter((todo) => !todo.done),
										{ key: 'id' },
									),
								);
								props.onTrace('clear-completed', { cleared }, event);
							}}
						>
							Clear completed
						</button>
					</Show>
				</footer>
			</Show>
		</section>
	);
}
